  ["quest:windurst:21"] = {
    objective_name = "Catch It If You Can!",
    page = {
      title = "Catch It If You Can!",
      page_id = 10174,
      revision_id = 1747815,
      revision_timestamp = "2021-10-24T11:25:25Z",
      content_sha256 = "b66d24df23d776b29e8fe6304f114a54cebafbd28d3af2d146a6b188a91cc72a",
      source_url = "https://ffxiclopedia.fandom.com/wiki/Catch_It_If_You_Can!",
      license = "CC-BY-SA-3.0",
    },
    steps = {
      {
        order = 1,
        marker = "*",
        depth = 1,
        instruction = "Get a rare or remarkable status ailment: Mute, Bane, or Plague. These are added effect from hits from specific mobs. The normal status ailments Silence, Curse, or Disease will not work.",
        action = "note",
        entities = { "Mute", "Bane", "Plague", "Silence", "Curse", "Disease" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 2,
        marker = "*",
        depth = 1,
        instruction = "Many of these effects will not last long, so it is best to set your home point at HP #1 in Port Windurst, which is very close to Ohruru, and carry a scroll of Instant Warp to get there quickly once you are afflicted.",
        action = "note",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 3,
        marker = "*",
        depth = 1,
        instruction = "Mute is given by Eight of Cups in the Outer Horutoto Ruins - Dahlia Tower (F-11) in West Sarutabaruta.",
        action = "note",
        entities = { "Mute", "Eight of Cups", "Outer Horutoto Ruins - Dahlia Tower (F-11)", "West Sarutabaruta" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = { "F-11" },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 4,
        marker = "**",
        depth = 2,
        instruction = "Eight of Cups inflicts Mute through an Additional Effect by its weapon. This will have a difficult time inflicting a high level player.",
        action = "note",
        entities = { "Eight of Cups", "Mute", "Additional Effect" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 5,
        marker = "**",
        depth = 2,
        instruction = "Mute in Beadeaux from \"The Mute\" does not work as it is actually Silence.",
        action = "note",
        entities = { "Mute", "Beadeaux", "Silence" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 6,
        marker = "*",
        depth = 1,
        instruction = "Bane is given by Lost Soul mages in the Eldieme Necropolis.",
        action = "note",
        entities = { "Bane", "Lost Soul", "Eldieme Necropolis" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 7,
        marker = "*",
        depth = 1,
        instruction = "Buffalo in Uleguerand Range can give you Plague, however its time affecting the player is limited (see talk page).",
        action = "talk",
        entities = { "Buffalo", "Uleguerand Range", "Plague" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 8,
        marker = "*",
        depth = 1,
        instruction = "Promathia can also inflict Plague. You can fight him on a lower difficulty of the high tier mission battlefield Dawn. It'll cost you 10 merit points per try, and you have to be careful which trusts you summon. Don't summon offensive trusts (they will kill him too quickly), and many of the healer trusts will cure you of Plague as soon as you catch it. Best choice is... Required details: Promathia, Plague, Dawn.",
        action = "fight",
        entities = { "Promathia", "Plague", "Dawn" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 9,
        marker = "*",
        depth = 1,
        instruction = "Deathmaw Orobon in Ceizak Battlegrounds can inflict Plague on a high level player with Vile Belch, however, the only way to get this quest done using them is to set your Home Point to the crystal directly outside of Ohruru's location and warp as soon as it is inflicted. It does not last long, but it's one of the few options for a Level 99.",
        action = "note",
        entities = { "Deathmaw Orobon", "Ceizak Battlegrounds", "Plague", "Vile Belch", "Ohruru" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 10,
        marker = "*",
        depth = 1,
        instruction = "Simply speak with Ohruru when you're afflicted with any of the status ailments.",
        action = "talk",
        entities = { "Ohruru" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 11,
        marker = "*",
        depth = 1,
        instruction = "She will give you 1,000gil for Mute, 1,200gil for Bane, or 1,500gil for Plague. She will also heal the status ailment.",
        action = "trade",
        entities = { "Mute", "Bane", "Plague" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
    },
    warnings = {  },
  },
